{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE Bot_csat as ( SELECT conversation_id, message_data.value:created_time::timestamp AS created_time, message_part.value:text:content::string AS message_content FROM freshchat_msg_final_v4_conversations_by_id, LATERAL FLATTEN(input => messages) AS message_data, LATERAL FLATTEN(input => message_data.value:message_parts) AS message_part WHERE message_data.value:actor_type::string = \'user\' AND message_part.value:text:content::string IN (\'Very Happy\', \'Happy\', \'Not Satisfied\', \'Sad\', \'Extremely Sad\') ); CREATE OR REPLACE TABLE snitch_db.maplemonk.contactratereasons AS ( WITH messages_exploded AS ( SELECT m.value:conversation_id::string AS conversation_id, m.value:created_time::timestamp AS created_time, m.value:actor_type::string AS actor_type, m.value:message_parts AS message_parts FROM freshchat_msg_final_v3_conversations_by_id fc, LATERAL FLATTEN(input => fc.MESSAGES) m ) SELECT DISTINCT t.conversation_id, t.created_time, t.content_msg FROM ( SELECT me.*, ROW_NUMBER() OVER (PARTITION BY me.conversation_id ORDER BY me.created_time ASC) AS rn, me.message_parts[0]:text:content::string AS content_msg FROM messages_exploded me WHERE me.actor_type = \'user\' ) t WHERE t.rn = 2 ); CREATE OR REPLACE TABLE Bot_csat_v2 AS SELECT A.conversation_id AS conversation_id_A, A.created_time AS user_message_time, A.message_content, B.conversation_id AS conversation_id_B, B.created_time AS previous_message_time, B.user_content, B.previous_content FROM ( SELECT conversation_id, message_data.value:created_time::timestamp AS created_time, message_part.value:text:content::string AS message_content FROM freshchat_msg_final_v4_conversations_by_id, LATERAL FLATTEN(input => messages) AS message_data, LATERAL FLATTEN(input => message_data.value:message_parts) AS message_part WHERE message_data.value:actor_type::string = \'user\' AND message_part.value:text:content::string IN (\'Very Happy\', \'Happy\', \'Not Satisfied\', \'Sad\', \'Extremely Sad\') ) AS A LEFT JOIN ( WITH messages_flat AS ( SELECT ROW_NUMBER() OVER (PARTITION BY t0.conversation_id ORDER BY t1.value:created_time::timestamp) AS msg_order, t0.conversation_id, t1.value:actor_type::string AS actor_type, TRIM(REGEXP_REPLACE(t1.value:message_parts[0]:text:content::string, \'[\n\r\t]+\', \'\')) AS content, t1.value:created_time::timestamp AS created_time FROM freshchat_msg_final_v4_conversations_by_id t0, LATERAL FLATTEN(input => t0.messages) t1 ) SELECT mf1.conversation_id, mf1.created_time, mf1.content AS user_content, mf2.content AS previous_content FROM messages_flat mf1 JOIN messages_flat mf2 ON mf1.conversation_id = mf2.conversation_id AND mf1.msg_order = mf2.msg_order + 1 WHERE mf1.actor_type = \'user\' AND REGEXP_LIKE(mf2.content, \'How can I help you today.*\', \'i\') ) AS B ON A.conversation_id = B.conversation_id;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            